WITH metrics AS (SELECT *, ROW_NUMBER() OVER (ORDER BY rating DESC, id) row_seq, LAST_VALUE(rating, TRUE) OVER w_hist last_known_rating FROM suppliers WINDOW w_hist AS (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, country, city, rating, row_seq, last_known_rating, CASE WHEN city RLIKE '^(London|Berlin)$' THEN 'GROUP_A' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'EXTENDED' ELSE 'CORE' END AS city_zone FROM metrics;
